import { useState, useEffect } from 'react';

function VehicleList({ user, onRent }) {
  const [vehicles, setVehicles] = useState([]);
  const [loading, setLoading] = useState(true);

  const fetchVehicles = async () => {
    setLoading(true);
    const res = await fetch('http://localhost:3002/api/vehicles');
    const data = await res.json();
    setVehicles(data);
    setLoading(false);
  };

  useEffect(() => {
    fetchVehicles();
  }, []);

  if (loading) return <div className="loading">Araçlar yükleniyor...</div>;

  const available = vehicles.filter((v) => v.available);

  return (
    <div className="vehicle-list">
      <h2>Müsait Araçlar</h2>
      {available.length === 0 ? (
        <p className="no-vehicles">Şu an müsait araç bulunmuyor.</p>
      ) : (
        <div className="vehicle-grid">
          {available.map((vehicle) => (
            <div key={vehicle.id} className="vehicle-card">
              <div className="vehicle-icon">🚗</div>
              <h3>{vehicle.brand} {vehicle.model}</h3>
              <div className="vehicle-details">
                <span className="badge">{vehicle.segment}</span>
                <p>📍 {vehicle.campus}</p>
                <p className="price">₺{vehicle.pricePerDay}/gün</p>
              </div>
              <button className="rent-btn" onClick={() => onRent(vehicle)}>
                Kirala
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default VehicleList;
